/**
 * Slice-1 contract tests against the real converted packs (generated by
 * `tools/convert_slice1.py` from the decoded pack-3/pack-6 artifacts).
 * Semantics asserted here were mined from `b.java`/`i.java`/`k.java` —
 * see docs/gameplay-mining/state-animation-map.md.
 */
class ClipContractTest {

    private val clip0 by lazy { Clip.load(asset("clips/clip0/clip.acpk")) }
    private val clip7 by lazy { Clip.load(asset("clips/clip7/clip.acpk")) }
    private val tile11 by lazy { Clip.load(asset("level0/tileset-11/clip.acpk")) }

    @Test fun `clip0 decodes with mined shape`() {
        assertEquals(393, clip0.animCount())
        assertEquals(1544, clip0.frameModule.size)
        assertEquals(368, clip0.moduleW.size)
    }

    @Test fun `clip7 decodes with mined shape`() {
        assertEquals(201, clip7.animCount())
        assertEquals(942, clip7.frameModule.size)
        assertEquals(332, clip7.moduleW.size)
    }

    @Test fun `frame pool fields are coherent`() {
        // every anim's frame span stays inside the pool
        for (a in 0 until clip0.animCount()) {
            val end = clip0.animFrameStart[a] + clip0.animFrameCount[a]
            assertTrue(end <= clip0.frameModule.size, "anim $a overruns pool")
        }
    }

    @Test fun `module index high bits resolve`() {
        // av | ((i & 0xC0) << 2) — modules can exceed 255
        val m0 = clip0.frameModuleIndex(0, 0)
        assertTrue(m0 in 0 until 368)
    }

    @Test fun `rect query returns hitbox for anim 0`() {
        val out = IntArray(4)
        clip7.rect(0, 0, 0, 0, out)
        assertTrue(out[2] > 0 && out[3] > 0, "hitbox w/h should be positive")
    }

    @Test fun `rect query mirrors x on flag bit0`() {
        val a = IntArray(4); val b = IntArray(4)
        clip7.rect(0, 0, 0, 0, a)
        clip7.rect(0, 0, 0, 1, b)
        assertEquals(-a[0] - a[2], b[0])
        assertEquals(a[1], b[1])
    }

    @Test fun `frameDraw returns the negated stored offset`() {
        // b.javap a(g,anim,frame,x,y,flags,i6,i7) @35-156:
        //   i10 = (flags&1)!=0 ? i6 + ax : i6 - ax ; drawX = i3 - i10
        // Callers fold the i6 ref into x and do `x - dx`, so the returned dx
        // is the NEGATED stored offset unflipped and the raw one flipped:
        //   drawX = x + ax (flags&1==0) / x - ax (flags&1==1).
        // clip93 anim 10 frame 0 is the menu-pill left cap with stored dx=+1
        // (proven ACPK): it must draw at x+1 so it overlaps the fill run —
        // the old sign put it at x-1 and opened the QUICK PLAY seam.
        val c = Clip.load(asset("clips/clip93/clip.acpk"))
        val fi = c.frameIndex(10, 0)
        assertEquals(1, c.frameDx[fi], "clip93 anim10/f0 stored dx (cap anchor nudge)")
        for (flags in intArrayOf(0, 1)) {
            val fd = c.frameDraw(10, 0, flags)
            val want = if (flags and 1 != 0) c.frameDx[fi] else -c.frameDx[fi]
            assertEquals(want, fd.dx, "dx sign for flags=$flags")
            val wantY = if (flags and 2 != 0) c.frameDy[fi] else -c.frameDy[fi]
            val fd2 = c.frameDraw(10, 0, flags or (flags shl 1))
            assertEquals(wantY, fd2.dy, "dy sign for flags=${flags or (flags shl 1)}")
        }
        // scratch overload agrees with the allocating one
        val out = Clip.FrameDraw(0, 0, 0, 0)
        c.frameDraw(10, 0, 0, out)
        assertEquals(c.frameDraw(10, 0, 0).dx, out.dx)
        assertEquals(c.frameDraw(10, 0, 0).dy, out.dy)
    }

    @Test fun `tileset cells index the object space`() {
        assertEquals(119, tile11.objPlaceCount.size)
        // each tile object = one placement
        for (o in 0 until tile11.objPlaceCount.size) {
            assertTrue(tile11.objPlaceCount[o] >= 1, "tile object $o empty")
        }
    }
}

class EntityFsmTest {

    private val clip by lazy { Clip.load(asset("clips/clip7/clip.acpk")) }

    @Test fun `setAnim resets counters and records previous`() {
        val e = Entity(11, clip)
        e.setAnim(7)
        e.T = 3; e.U = 1
        e.setAnim(4)
        assertEquals(7, e.Q)
        assertEquals(4, e.S)
        assertEquals(0, e.T); assertEquals(0, e.U)
    }

    @Test fun `out of range setAnim is rejected`() {
        val e = Entity(11, clip)
        e.setAnim(7)
        e.setAnim(999)
        assertEquals(7, e.S)
    }

    @Test fun `advanceAnim wraps at end like s()`() {
        val e = Entity(11, clip)
        e.setAnim(2)               // single-frame anim
        e.advanceAnim()            // U=1 > dur? wraps via T overflow
        var guard = 0
        while (!e.animFinished() && guard++ < 1000) e.advanceAnim()
        // now at last frame/last tick; one more advance wraps to frame 0
        e.advanceAnim()
        assertEquals(0, e.T)
        assertEquals(0, e.U)
    }

    @Test fun `P bit6 blocks advance`() {
        val e = Entity(11, clip)
        e.setAnim(0)
        e.P = e.P or 64
        e.advanceAnim()
        assertEquals(0, e.U)
    }

    @Test fun `integrate applies vel and anchor resync`() {
        val e = Entity(11, clip)
        e.setPositionPx(100, 50)
        e.ag = 2560   // 10 px/tick
        e.integrate()
        assertEquals(110, e.ak)
        assertEquals(110 shl 8, e.N)
    }
}

class Level0WorldTest {

    @Test fun `level decodes pack-6 shape`() {
        val w = world()
        assertEquals(627, w.level.cols)
        assertEquals(55, w.level.rows)
        assertEquals(637, w.level.entities.size)
        assertEquals(4, w.level.layers.size)
    }

    @Test fun `player spawns from a type-0 or 25 record`() {
        val w = world()
        assertNotNull(w.level.playerSpawn(), "level 0 must carry a spawn record")
    }

    @Test fun `collision out of bounds is solid sentinel 20`() {
        val w = world()
        assertEquals(20, w.level.collisionCell(-1, 0))
        assertEquals(20, w.level.collisionCell(0, -1))
        assertEquals(20, w.level.collisionCell(0, 55))
    }

    @Test fun `NPC family entities spawn at record positions`() {
        val w = world()
        assertTrue(w.npcs.isNotEmpty(), "expected clip-7 family entities")
        // record positions are authoritative — several records sit outside
        // the tile grid (ax9 at y=1106 > worldH=1100; ax74s at x>12540)
        // and the original spawns them unclamped.
        val byAw = w.level.entities.associate { it[1] to (it[2] to it[3]) }
        for (n in w.npcs) {
            val exp = byAw[n.aw]
            if (exp != null) {
                if (n.ax == 11 || n.ax == 73) {
                    // ctor tail `a(true);E()` (i.javap L7200-L7233) settles
                    // soldiers at spawn: a(true) pushes ak out of walls and
                    // the real E() loop (`a(1)` per pass, `al+=10` until
                    // the foot cell is standable) snaps al to the cell top
                    // — a few px up (-4 on level 0) or down (+35).
                    assertTrue(kotlin.math.abs(n.ak - exp.first) <= 10 &&
                        n.al >= exp.second - 8 && n.al <= exp.second + 40,
                        "ax${n.ax} aw=${n.aw} settled pos near (${exp.first},${exp.second}) got (${n.ak},${n.al})")
                } else {
                    assertEquals(exp, n.ak to n.al,
                        "ax${n.ax} aw=${n.aw} should sit at its record position")
                }
            }
        }
    }

    @Test fun `player falls with gravity and lands on solid ground`() {
        val w = world()
        // settle: run ticks until landing or timeout
        var ticks = 0
        while (w.player.ah != 0 && ticks++ < 600) w.tick(emptyList())
        assertEquals(0, w.player.ah, "player should have landed")
        val feetCell = w.level.collisionCell(w.player.ak / 20, (w.player.al + 1) / 20)
        // feet cell may be one row below the anchor depending on hitbox;
        // assert the *supporting* cell is solid or one-way
        val v1 = w.level.collisionAtPx(w.player.ak, w.player.al + 1)
        val v2 = w.level.collisionAtPx(w.player.ak, w.player.al + 21)
        assertTrue(w.level.isSolid(v1) || w.level.isOneWay(v1) ||
                   w.level.isSolid(v2) || w.level.isOneWay(v2) ||
                   w.level.isSolid(feetCell),
            "player should rest on ground (got $v1/$v2/$feetCell)")
    }

    @Test fun `long falls cannot tunnel through floors (terminal velocity 5120)`() {
        // g.java:578 (proven): ah capped at 5120 = 20px/tick = one cell,
        // which is what stops high-speed descents skipping a floor row.
        val w = world()
        val p = w.player
        // settle first so spawn X sits on real ground
        var t = 0
        while (p.ah != 0 && t++ < 600) w.tick(emptyList())
        val floorY = p.al
        // drop from 20 cells up in fall state S=43
        p.al = floorY - 20 * 20
        p.setAnim(43)
        t = 0
        while (p.ah != 0 && t++ < 600) w.tick(emptyList())
        assertTrue(p.al <= floorY + 21,
            "player tunneled through floor: al=${p.al} floor=$floorY")
    }

    @Test fun `hold-right runs the player forward`() {
        val w = world()
        // Start past the spawn-intro ax5 claim zone [49,863,116,941] —
        // now that the player carries its record uid (findByAw), the
        // first tap binds the claim and its script hijacks the run.
        w.player.setPositionPx(300, 940); w.player.refreshBoxes()
        val x0 = w.player.ak
        val q = InputQueue()
        // MR cell (cell5) -> mask 64 -> u(8256) held RIGHT (k.java:489)
        val (rx, ry) = w.cellPoint(5)
        q.post(InputQueue.Type.DOWN, rx, ry)
        repeat(30) { w.tick(q.drainTo(q.headSequence())) }
        assertTrue(w.player.ak > x0, "player should have moved right")
        // run cap ±2560 (proven literal from g.e()/ax())
        assertTrue(w.player.ag <= 2560)
    }

    @Test fun `player run uses clip0 anim 12 after run-start`() {
        val w = world()
        // settle so the press lands while grounded
        var t = 0
        while (w.player.ah != 0 && t++ < 600) w.tick(emptyList())
        // start past the spawn-intro ax5 claim zone [49,863,116,941] — else
        // the first tap binds it and velClampTail locks the run mid-vault.
        w.player.setPositionPx(300, 940)
        w.kM(2)
        val q = InputQueue()
        // hold RIGHT (MR cell5 → mask 64): the tap edge fires the proven
        // vault-jump (S233), and the aS-edge-bump in land() keeps aZ
        // correct after landing.
        val (rx, ry) = w.cellPoint(5)
        q.post(InputQueue.Type.DOWN, rx, ry)
        var seen = false
        repeat(200) {
            w.tick(q.drainTo(q.headSequence()))
            if (w.player.S == 12 || w.player.S == 32) seen = true
        }
        assertTrue(seen, "expected run anims 32/12 at some point, last S=${w.player.S}")
    }

    @Test fun `tap top third jumps through 21-22-23-43-5 landing chain`() {
        val w = world()
        val q = InputQueue()
        // settle first — the spawn-adjacent ax5 zone claims its intro
        // script here (k.C bound; aa() L341 zeros player velocity while
        // the script steps — the original's cutscene lock). Release it
        // and walk to open ground so the jump isn't script-locked or
        // support-variant S233.
        repeat(10) { w.tick(emptyList()) }
        w.kC?.releaseClaim(w); w.kC = null
        w.player.setPositionPx(600, w.player.al)
        // wait for the landing — x600 sits over a drop, and the jump tail
        // (`cq && v(action)`) only fires while an l()-family arm re-arms
        // cq this tick — i.e. the press must land while grounded.
        var grounded = false
        repeat(80) {
            w.tick(emptyList())
            if (w.player.aZ && w.player.S == 0) { grounded = true; return@repeat }
        }
        assertTrue(grounded, "player should settle grounded before the tap")
        val (ux, uy) = w.cellPoint(1)
        q.post(InputQueue.Type.DOWN, ux, uy)
        val seen = HashSet<Int>()
        repeat(200) {
            w.tick(q.drainTo(q.headSequence()))
            if (it == 1) q.post(InputQueue.Type.UP, ux, uy)
            seen += w.player.S
        }
        // jump chain: squat 21 -> rise 22/23/233 -> fall 43 -> land 5
        assertTrue(21 in seen || 22 in seen || 23 in seen || 233 in seen,
            "expected jump anims, saw $seen")
        assertTrue(43 in seen || 5 in seen,
            "expected fall/land, saw $seen")
    }

    @Test fun `ax11 soldiers patrol off their home cell`() {
        val w = world()
        val soldiers = w.npcs.filter { it.ax == 11 }
        assertTrue(soldiers.isNotEmpty(), "expected ax11 records in level 0")
        val homes = soldiers.map { it.ak }
        // au>=2 entities freeze verbatim (k.java L25f) and ax11 owns
        // P|16 itself — hold the player beside a soldier so the camera
        // keeps it in-play, exactly like a real walk-by.
        val s0 = soldiers.first()
        repeat(120) {
            w.player.setPositionPx(s0.ak + 20, s0.al)
            w.tick(emptyList())
        }
        val moved = soldiers.zip(homes).count { (e, hx) -> kotlin.math.abs(e.ak - hx) > 8 }
        assertTrue(moved > 0, "no soldier patrolled: ${soldiers.map { it.S }}")
    }

    @Test fun `soldier alerts and chases when player enters the zone box`() {
        val w = world()
        // park the player inside a soldier's Z[9..12] alert box
        val s = w.npcs.firstOrNull { it.ax == 11 } ?: return
        repeat(5) { w.tick(emptyList()) }
        w.player.setPositionPx(s.Z[9] + 5, s.al)
        // b() (i.java:1546) gates the spot on v() → au<=i, i.e. the
        // entity must be near the CAMERA — teleporting the player leaves
        // the cam behind; snap it like a real scroll would.
        w.kO = s.ak - 200; w.kP = s.al - 120; w.rebuildCamRect()
        var alerted = false
        repeat(90) {
            // the aA==0 → a() body-push (i.java:6246) shoves the player
            // each tick — re-park inside the zone like real input would;
            // an ax69 zone may bind af mid-run and blind l() (i.java:2290)
            w.player.setPositionPx(s.ak + 5, s.al)
            w.player.af = null
            w.tick(emptyList())
            if (s.aA != 0 || s.S == 5 || s.S == 4 || s.S == 23) alerted = true
        }
        assertTrue(alerted, "soldier should alert on player in zone (S=${s.S}, aA=${s.aA})")
    }

    @Test fun `alerted soldier strikes the player in melee range`() {
        val w = world()
        val s = w.npcs.firstOrNull { it.ax == 11 } ?: return
        repeat(5) { w.tick(emptyList()) }
        // stand the player next to the soldier inside its alert box
        w.player.setPositionPx(s.ak + 30, s.al)
        var struck = false
        repeat(200) {
            w.tick(emptyList())
            w.player.setPositionPx(s.ak + 30, s.al)   // keep in reach
            if (w.player.x1 < 90 || w.player.hitsTaken > 0 || w.player.S == 43)
                struck = true
        }
        assertTrue(struck,
            "soldier should land hits (S=${s.S}, x1=${w.player.x1})")
    }

    @Test fun `player vault attack damages and kills a soldier`() {
        val w = world()
        val s = w.npcs.firstOrNull { it.ax == 11 } ?: return
        repeat(5) { w.tick(emptyList()) }
        val hp0 = s.aB
        // pin player overlapping the soldier in an attack anim (67 sword combo)
        var sawDamage = false
        repeat(300) {
            w.player.setPositionPx(s.ak, s.al)
            if (w.player.S != 67) w.player.setAnim(67)
            s.setAnim(0)     // soldier fights back now (hit-react → i(6)
                            // lunge → strike → player stagger); pin passive
                            // to isolate the j() damage-intake chain
            w.tick(emptyList())
            if (s.aB < hp0) sawDamage = true
        }
        assertTrue(sawDamage, "player attacks should damage the soldier (aB=${s.aB})")
        // enough hits → aB<=0 → i(0) → i(139) corpse
        var corpse = false
        repeat(400) {
            w.player.setPositionPx(s.ak, s.al)
            if (s.aB > 0 && w.player.S != 67) w.player.setAnim(67)
            s.setAnim(0)
            w.tick(emptyList())
            if (s.S == 139) corpse = true
        }
        assertTrue(s.aB <= 0 && corpse,
            "soldier should die to corpse S139 (aB=${s.aB}, S=${s.S})")
    }

    @Test fun `bottom-zone tap swings the sword and can kill a soldier`() {
        val w = world()
        val s = w.npcs.firstOrNull { it.ax == 11 } ?: return
        // walk the player to the soldier and tap attack (bottom-third zone).
        // Slice 389: the soldier now spawns on the real E() ground line, and
        // the player's box bottom sits a couple of px higher than the
        // soldier's, so a bare teleport to `s.al` leaves him airborne (S43/5
        // flicker, no attack) — settle the player like the original does.
        fun stand(x: Int, y: Int) { w.player.setPositionPx(x, y); w.player.eSettle(w) }
        stand(s.ak - 20, s.al)
        w.tick(emptyList())
        var sawSlash = false; var kill = false
        repeat(600) {
            if (s.aB <= 0) { kill = true; return@repeat }
            stand(s.ak - 20, s.al)
            s.setAnim(0)     // pin passive — the soldier now counterattacks
                            // faithfully; this test covers the kill chain
            val (cx, cy) = w.cellPoint(4)
            w.tick(listOf(InputQueue.Event(0, InputQueue.Type.DOWN, cx, cy),
                          InputQueue.Event(1, InputQueue.Type.UP, cx, cy)))
            if (w.player.S in intArrayOf(67, 68, 69, 112, 113, 114, 115, 81)) sawSlash = true
        }
        assertTrue(sawSlash, "tap should enter the sword combo (S=${w.player.S})")
        assertTrue(kill, "combo hits should kill the soldier (aB=${s.aB}, S=${s.S})")
    }

    @Test fun `assassination finisher kills a weakened locked soldier`() {
        val w = world()
        settleIntro(w)                 // I() L108 gate: tests run post-intro
        val s = w.npcs.firstOrNull { it.ax == 11 } ?: return
        // the player is about to stand next to this soldier — put the
        // camera where it would be (k.O/k.P) so u() scores it in-play;
        // ax11's own arm clears P|16 when aA==0 so keep-live can't help.
        w.kO = s.ak - 200; w.kP = s.al - 120; w.rebuildCamRect()
        repeat(5) { w.tick(emptyList()) }
        // Verbatim weaken chain (i.java:1955): Z[0]==1 marks the soldier
        // weaken-eligible; a hit leaving aB<=bu → C() flips Z0=2 + S144.
        // (Level-0 records carry Z0=0 — they never weaken, proven.)
        s.Z[0] = 1
        s.aB = 120
        // +4px: feet must embed into the floor row (W[3]+1 inside cell-5)
        // or x() reports aZ=false and the :2473 arm falls before the hit
        // lands — same in the original.
        w.player.setPositionPx(s.ak - 20, s.al + 4)
        // Land a normal hit to trip the weaken: H=50 → aB=70 → hitReact
        // Z0==1 → Z0=2 + S144 + claims the aN lock. The soldier ticks
        // before the player (G12) and reads the boxes the player's last
        // t() left — refresh them as a finished frame would.
        w.player.setAnim(67); w.player.refreshBoxes()
        // the swing lands on the frame the attack box is live — one tick
        // later than under the old player-first order
        var hitT = 0
        while (hitT++ < 8 && s.Z[0] != 2) w.tick(emptyList())
        assertTrue(s.Z[0] == 2 && s.S == 144,
            "hit on Z0==1 soldier should weaken: Z0=2+S144 (got Z0=${s.Z[0]}, S=${s.S})")
        assertTrue(w.lockTarget === s,
            "weakened soldier should hold the aN lock")
        // The weakened soldier BLOCKS further normal attacks from S144: the
        // arm's own counter (I() @5342-5451, slice 402) — `aS.i(8)` recoil +
        // `k.E.P|=128`, the soldier stays in S144 (the `h()`/`i()` engage into
        // S17 is the shared tail's @7479, which S144's `goto 7691` skips).
        var recoiled = false
        for (i in 0 until 30) {
            w.player.setPositionPx(s.ak - 20, s.al); w.player.refreshBoxes()
            val (cx, cy) = w.cellPoint(4)
            w.tick(listOf(InputQueue.Event(0, InputQueue.Type.DOWN, cx, cy),
                          InputQueue.Event(1, InputQueue.Type.UP, cx, cy)))
            if (w.player.S == 8) { recoiled = true; break }
            if (s.S != 144) break
        }
        assertTrue(recoiled && s.S == 144,
            "weakened soldier should block the next attack in place " +
                "(player S${w.player.S}, soldier S${s.S})")
        // S216 is h()-exempt (i.java:1272): it reaches j()'s finisher arm
        // (i.java:1334) — aB=0 + diagonal launch (ag=±5120, ai=∓2560).
        // Wait out S144 (r() → i(23)): the finisher lands in the shared
        // tail's j() intake, which S23 arms (tail[2]).
        for (i in 0 until 90) {
            w.player.setPositionPx(s.ak - 20, s.al); w.player.refreshBoxes()
            w.tick(emptyList())
            if (s.S != 144) break
        }
        assertTrue(s.S != 144, "the block should resolve (sS=${s.S})")
        w.player.setAnim(216)
        for (i in 0 until 60) {
            w.player.setPositionPx(s.ak - 20, s.al); w.player.refreshBoxes()
            w.tick(emptyList())
            if (s.aB <= 0) break          // check the launch before friction decays it
        }
        assertTrue(s.aB <= 0,
            "S216 finisher should zero the victim (aB=${s.aB})")
        // i.g() (i.java:1237) zeroes ag/ai unconditionally — the ±5120
        // launch written before it is dead in the original; the victim
        // lands in S85 (the c(85,157) path) with ag=0.
        assertTrue(s.S == 85 || s.ag == 0,
            "S216 victim should sit in S85 with the launch eaten by g() (S=${s.S}, ag=${s.ag})")
    }

        @Test fun `npc strike on a metered player pays meter and staggers the player`() {
        val w = world()
        // pick a soldier whose strike-adjacent position passes i.c()'s
        // wall guard (open-air spots legitimately block the drain)
        var sv: Entity? = null
        var sdx = 0
        for (cand in w.npcs.filter { it.ax == 11 }) {
            keepLive(cand)
            cand.setAnim(12)
            w.tick(emptyList())               // S12's swing rect exists from T=1
            cand.refreshBoxes()               // off-screen soldiers don't t() on their own
            // the strike X box is a clip-data rect (east or west of ak)
            // — stand the player inside its x-span on a grounded cell:
            // airborne victims fall out (op20, no S9) and off-side
            // spots simply never overlap the swing. Frame 0's X is a point
            // at the anchor (slice 389: the settled spawn rows made such a
            // point-box candidate the first hit), so demand a real rect.
            if (cand.X[2] - cand.X[0] <= 2) continue
            outer@ for (face in booleanArrayOf(cand.av, !cand.av)) {
                cand.av = face; cand.refreshBoxes()
                for (dx in -60..60) {
                    w.player.setPositionPx(cand.ak + dx, cand.al)
                    w.player.eSettle(w)           // slice 389: ground line
                    w.player.refreshBoxes()
                    w.player.probeCells(w)
                    if (!w.player.nearLeftWall(w) && w.player.aZ &&
                        Entity.overlapI(w.player.W, cand.X)) { sv = cand; sdx = dx; break@outer }
                }
            }
            if (sv != null) break
        }
        sv = assertNotNull(sv, "no grounded strike-adjacent spot found")
        var playerHit = false
