            if (w.player.S == 9) { playerHit = true; break }
        }
        assertTrue(playerHit, "strike on metered player → r9.c(r13) → player S9")
        assertTrue(w.player.x1 < 90, "g.a() pays meter u[0]=5 (x1=${w.player.x1})")
    }

